-- China: Season 4 National Open (Chengdu) prizes and gift pack, plus the
-- 1st Anniversary collector's playing cards. 9 items, Chinese.
-- Safe to run more than once (name + language already present = skipped).
with incoming(ord, data) as (values
  (1, $j${"cat": "PROMO", "nm": "Jayce - Brilliant Inventor (National Open S4 Champion)", "ev": "NO - China", "se": "VEN", "ty": "Card", "tg": "Champion Unit\nJayce\nPiltover\nNational Open\nChampion Stamp", "do": "Mind", "ra": "Overnumber/Alternate Art", "cn": "068b/166", "inf": "Season 4 National Open in Chengdu (China). Prize cards by final placing: Champion, Top 4 and Top 8 receive Jayce, Brilliant Inventor in the new Peak Collection art (巅峰臻藏) with a placing stamp; Top 64 receives the alternate-art version (异画版本). Season 4 National Opens also continue to give out the Legend Master award.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-champion-cn.webp", "pt": "By itself", "fo": true, "tn": true}$j$::jsonb),
  (2, $j${"cat": "PROMO", "nm": "Jayce - Brilliant Inventor (National Open S4 Top 4)", "ev": "NO - China", "se": "VEN", "ty": "Card", "tg": "Champion Unit\nJayce\nPiltover\nNational Open\nTop 4 Stamp", "do": "Mind", "ra": "Overnumber/Alternate Art", "cn": "068b/166", "inf": "Season 4 National Open in Chengdu (China). Prize cards by final placing: Champion, Top 4 and Top 8 receive Jayce, Brilliant Inventor in the new Peak Collection art (巅峰臻藏) with a placing stamp; Top 64 receives the alternate-art version (异画版本). Season 4 National Opens also continue to give out the Legend Master award.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-top4-cn.webp", "pt": "By itself", "fo": true, "tn": true}$j$::jsonb),
  (3, $j${"cat": "PROMO", "nm": "Jayce - Brilliant Inventor (National Open S4 Top 8)", "ev": "NO - China", "se": "VEN", "ty": "Card", "tg": "Champion Unit\nJayce\nPiltover\nNational Open\nTop 8 Stamp", "do": "Mind", "ra": "Overnumber/Alternate Art", "cn": "068b/166", "inf": "Season 4 National Open in Chengdu (China). Prize cards by final placing: Champion, Top 4 and Top 8 receive Jayce, Brilliant Inventor in the new Peak Collection art (巅峰臻藏) with a placing stamp; Top 64 receives the alternate-art version (异画版本). Season 4 National Opens also continue to give out the Legend Master award.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-top8-cn.webp", "pt": "By itself", "fo": true, "tn": true}$j$::jsonb),
  (4, $j${"cat": "PROMO", "nm": "Jayce - Brilliant Inventor (National Open S4 Top 64)", "ev": "NO - China", "se": "VEN", "ty": "Card", "tg": "Champion Unit\nJayce\nPiltover\nNational Open\nTop 64 Stamp", "do": "Mind", "ra": "Overnumber/Alternate Art", "cn": "068a/166", "inf": "Season 4 National Open in Chengdu (China). Prize cards by final placing: Champion, Top 4 and Top 8 receive Jayce, Brilliant Inventor in the new Peak Collection art (巅峰臻藏) with a placing stamp; Top 64 receives the alternate-art version (异画版本). Season 4 National Opens also continue to give out the Legend Master award.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-top64-cn.webp", "pt": "By itself", "fo": true, "tn": true}$j$::jsonb),
  (5, $j${"cat": "PROMO", "nm": "Jayce - Brilliant Inventor (National Open S4 Participation)", "ev": "NO - China", "se": "VEN", "ty": "Card", "tg": "Champion Unit\nJayce\nPiltover\nNational Open\nParticipation Stamp", "do": "Mind", "ra": "Overnumber/Alternate Art", "cn": "068/166", "inf": "Participation commemorative card (参赛纪念卡牌) in the entry gift pack every player received at the Season 4 National Open in Chengdu (China), with the participation stamp. The gift pack also held a Card Brick (one of two designs at random), a pack of Akali's Ninja Tools art sleeves and 2 Vendetta booster packs.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-participation-cn.webp", "pt": "By itself", "fo": true, "tn": true}$j$::jsonb),
  (6, $j${"cat": "COLLECTIBLE", "nm": "National Open Season 4 Card Brick (Renekton)", "ev": "NO - China", "se": "VEN", "ty": "Card Brick", "tg": "Card Brick\nCard Display Holder\nNational Open\nRenekton", "do": "N/A", "ra": "N/A", "cn": "N/A", "inf": "Part of the entry gift pack every player received at the Season 4 National Open in Chengdu (China). Player Card Brick (选手卡砖) on a red lanyard; one of two designs given out at random.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-brick-renekton-cn.webp", "pt": "Entry gift pack", "tn": true}$j$::jsonb),
  (7, $j${"cat": "COLLECTIBLE", "nm": "National Open Season 4 Card Brick (Nasus)", "ev": "NO - China", "se": "VEN", "ty": "Card Brick", "tg": "Card Brick\nCard Display Holder\nNational Open\nNasus", "do": "N/A", "ra": "N/A", "cn": "N/A", "inf": "Part of the entry gift pack every player received at the Season 4 National Open in Chengdu (China). Player Card Brick (选手卡砖) on a blue lanyard; one of two designs given out at random.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-brick-nasus-cn.webp", "pt": "Entry gift pack", "tn": true}$j$::jsonb),
  (8, $j${"cat": "COLLECTIBLE", "nm": "Akali's Ninja Tools Art Sleeves (National Open S4)", "ev": "NO - China", "se": "VEN", "ty": "Sleeves", "tg": "Sleeves\nAkali\nNational Open", "do": "N/A", "ra": "N/A", "cn": "N/A", "inf": "Part of the entry gift pack every player received at the Season 4 National Open in Chengdu (China). Art sleeves 阿卡丽的忍具 (Akali's Ninja Tools), 20 sleeves per pack.", "la": "Chinese", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/no-s4-sleeves-cn.webp", "pt": "Entry gift pack", "tn": true}$j$::jsonb),
  (9, $j${"cat": "COLLECTIBLE", "nm": "Riftbound 1st Anniversary Collector's Playing Cards", "ev": "China", "se": "N/A", "ty": "Playing Cards", "tg": "Playing Cards\n1st Anniversary", "do": "N/A", "ra": "N/A", "cn": "N/A", "inf": "符文战场一周年收藏扑克: a deck of playing cards for Riftbound's first anniversary in China, with champion illustrations on the face cards (Volibear, Miss Fortune, Viktor, Garen, Jinx, Yasuo, Kai'Sa, Lux, Darius, Ahri, Teemo and more).", "la": "Chinese", "pt": "Boxed deck"}$j$::jsonb)
),
base as (select coalesce(max(r), 0) as mr from promo_items),
casing as (select coalesce((select data->>'st' from promo_items where upper(data->>'st') = 'NEED' limit 1), 'NEED') as st),
fresh as (
  select i.ord, i.data from incoming i
  where not exists (select 1 from promo_items p
    where lower(trim(p.data->>'nm')) = lower(trim(i.data->>'nm')) and coalesce(p.data->>'la','') = coalesce(i.data->>'la',''))
),
numbered as (select data, (select mr from base) + row_number() over (order by ord) as nr from fresh)
insert into promo_items (id, r, data)
select 'item-' || n.nr, n.nr, n.data || jsonb_build_object('r', n.nr, 'id', 'item-' || n.nr, 'st', c.st)
from numbered n cross join casing c
returning id, data->>'nm' as name;
